public ImportResult importUsers(Path file, String operator) {
    log.info("开始导入 users file={} size={} operator={}", file, size(file), operator);
    int ok = 0, fail = 0, line = 0;
    List<RowError> errors = new ArrayList<>();
    try (BufferedReader r = Files.newBufferedReader(file, UTF_8)) {
        String header = r.readLine();
        if (!validHeader(header)) throw new ImportFileException("表头不合法: " + header);
        String l;
        while ((l = r.readLine()) != null) {
            line++;
            try { save(parse(l)); ok++; }
            catch (Exception e) {
                fail++;
                if (errors.size() < 100) errors.add(new RowError(line, e.getMessage()));
                log.warn("导入失败 line={} reason={}", line, e.toString());   // 不打印整行原文
            }
            if (line % 1000 == 0) log.info("进度 line={} ok={} fail={}", line, ok, fail);
        }
    } catch (IOException e) {
        log.error("导入中断 file={} operator={}", file, operator, e);
        throw new ImportFileException("读取文件失败: " + file, e);
    }
    log.info("导入结束 file={} total={} ok={} fail={}", file, line, ok, fail);
    return new ImportResult(ok, fail, errors);
}

